#!/usr/bin/env bash
ssh_key_state() { validate_target_user || return 2; SSH_USER="$(get_target_user)"; SSH_GROUP="$(id -gn "$SSH_USER")"; SSH_KEY="$(target_path "$SSH_KEY_PATH")" || return 2; SSH_PUB="${SSH_KEY}.pub"; SSH_DIR="$(dirname -- "$SSH_KEY")"; SSH_PROBLEMS=(); SSH_REPAIRABLE=(); [ -d "$SSH_DIR" ] || SSH_PROBLEMS+=("ssh dir missing"); [ ! -e "$SSH_DIR" ] || [ -d "$SSH_DIR" ] || SSH_PROBLEMS+=("ssh dir not directory"); for f in "$SSH_KEY" "$SSH_PUB"; do [ -e "$f" ] && [ ! -f "$f" ] && SSH_PROBLEMS+=("$f is not regular file"); done; [ -f "$SSH_KEY" ] || SSH_PROBLEMS+=("private key missing"); [ -f "$SSH_PUB" ] || SSH_PROBLEMS+=("public key missing"); if [ -d "$SSH_DIR" ]; then [ "$(stat -c %a "$SSH_DIR" 2>/dev/null)" = 700 ] || SSH_REPAIRABLE+=("chmod 700 $SSH_DIR"); [ "$(stat -c %U "$SSH_DIR" 2>/dev/null)" = "$SSH_USER" ] || SSH_REPAIRABLE+=("chown $SSH_DIR"); fi; if [ -f "$SSH_KEY" ]; then [ "$(stat -c %a "$SSH_KEY")" = 600 ] || SSH_REPAIRABLE+=("chmod 600 $SSH_KEY"); [ "$(stat -c %U "$SSH_KEY")" = "$SSH_USER" ] || SSH_REPAIRABLE+=("chown $SSH_KEY"); fi; if [ -f "$SSH_PUB" ]; then [ "$(stat -c %a "$SSH_PUB")" = 644 ] || SSH_REPAIRABLE+=("chmod 644 $SSH_PUB"); [ "$(stat -c %U "$SSH_PUB")" = "$SSH_USER" ] || SSH_REPAIRABLE+=("chown $SSH_PUB"); fi; if [ -f "$SSH_KEY" ] && [ -f "$SSH_PUB" ] && need_cmd ssh-keygen; then local derived actual; derived="$(ssh-keygen -y -f "$SSH_KEY" 2>/dev/null || true)"; actual="$(awk '{print $1" "$2}' "$SSH_PUB" 2>/dev/null || true)"; [ -z "$derived" ] || [ "$derived" = "$actual" ] || SSH_PROBLEMS+=("public key does not match private key"); fi; }
ssh_key_module_check() { ssh_key_state || return 2; if [ "${#SSH_PROBLEMS[@]}" -eq 0 ] && [ "${#SSH_REPAIRABLE[@]}" -eq 0 ]; then echo "ssh key pair valid"; return 0; fi; printf '%s ' "${SSH_PROBLEMS[@]}" "${SSH_REPAIRABLE[@]}"; echo; return 1; }
ssh_key_module_plan() { ssh_key_state || return 2; local p; for p in "${SSH_PROBLEMS[@]}"; do plan_warn "$p"; done; for p in "${SSH_REPAIRABLE[@]}"; do if [ "$REPAIR_PERMISSIONS" = 1 ]; then plan_change "$p"; else plan_warn "$p (requires --repair-permissions)"; fi; done; [ "${#SSH_PROBLEMS[@]}${#SSH_REPAIRABLE[@]}" = 00 ] && plan_ok "ssh key pair valid"; return 0; }
ssh_key_module_apply() { ssh_key_state || return 2; if [ -e "$SSH_KEY" ] || [ -e "$SSH_PUB" ]; then if [ "${#SSH_REPAIRABLE[@]}" -gt 0 ] && [ "$REPAIR_PERMISSIONS" = 1 ]; then run_root chown "$SSH_USER:$SSH_GROUP" "$SSH_DIR" "$SSH_KEY" "$SSH_PUB" 2>/dev/null || true; [ -d "$SSH_DIR" ] && run_root chmod 700 "$SSH_DIR"; [ -f "$SSH_KEY" ] && run_root chmod 600 "$SSH_KEY"; [ -f "$SSH_PUB" ] && run_root chmod 644 "$SSH_PUB"; echo "ssh permissions repaired"; return 0; fi; echo "existing SSH files are not overwritten; use --repair-permissions for ownership/mode only"; return 2; fi; run_root install -d -m 700 -o "$SSH_USER" -g "$SSH_GROUP" "$SSH_DIR"; run_as_target_user ssh-keygen -t ed25519 -C "$SSH_KEY_COMMENT" -f "$SSH_KEY" -N ''; run_root chmod 600 "$SSH_KEY"; run_root chmod 644 "$SSH_PUB"; }
